/**
 * Sumber tunggal warna status STPL Unit Hilang.
 * DISAMAKAN dengan Document States (meta.states) doctype "STPL Unit Hilang" —
 * warna yang dipakai indikator Frappe (form & list). Dipakai untuk pill status
 * di list card portal. Selaras dengan pola ttsStatus.js / deviasiStatus.js.
 */

// status → nama warna Frappe (persis dari Document States doctype).
const STATE_COLOR = {
	Draft: 'blue',
	'Menunggu Approval': 'orange',
	Approved: 'green',
	Rejected: 'red',
}

// Daftar status urut sesuai alur (draft → approval → terminal). Dipakai
// sub-sheet filter status (pilih banyak → operator Frappe `in`).
export const STATUS_OPTIONS = Object.keys(STATE_COLOR)

// Tebak warna untuk status tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	if (/Pending|Menunggu|Review|Request/i.test(s)) return 'orange'
	if (/Reject|Hilang|Failed|Cancel|Error/i.test(s)) return 'red'
	if (/Approved|Done|Success|Complete/i.test(s)) return 'green'
	if (/Draft|Submitted/i.test(s)) return 'blue'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk badge status di card.
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
export function statusPillClass(status) {
	return PILL[statusColor(status)] || PILL.gray
}

// Titik (border lingkaran) untuk picker status di sheet filter.
const DOT = {
	gray: 'border-ui-line-gray-400',
	blue: 'border-ui-line-blue-500',
	orange: 'border-ui-line-orange-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
}
export function statusDotClass(status) {
	return DOT[statusColor(status)] || DOT.gray
}
